package com.patientmanagement.patientservice.security;

import com.patientmanagement.patientservice.repository.UserRepository;
import com.patientmanagement.patientservice.model.UserEntity; // Ensure this import exists and is correct
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.security.core.userdetails.UserDetailsService;
import org.springframework.security.core.userdetails.UsernameNotFoundException;
import org.springframework.stereotype.Service;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.util.StringUtils;
import org.springframework.transaction.annotation.Transactional; // Use Spring's Transactional

@Service
public class CustomUserDetailsService implements UserDetailsService {

    private static final Logger logger = LoggerFactory.getLogger(CustomUserDetailsService.class);

    private final UserRepository userRepository;

    public CustomUserDetailsService(UserRepository userRepository) {
        this.userRepository = userRepository;
    }

    @Transactional(readOnly = true)
    public UserDetails loadUserByUsername(String username) throws UsernameNotFoundException {
        if (!StringUtils.hasText(username)) {
            logger.warn("Attempted to load user with empty or null username");
            throw new UsernameNotFoundException("Username cannot be null or empty");
        }
        String trimmedUsername = username.trim();
        logger.debug("Loading user details for username: {}", trimmedUsername);
        UserEntity user = userRepository.findByUsername(trimmedUsername)
                .orElseThrow(() -> {
                    logger.warn("User not found with username: {}", trimmedUsername);
                    return new UsernameNotFoundException("User not found with username: " + trimmedUsername);
                });
        logger.debug("Successfully loaded user: {} with {} authorities", user.getUsername(), user.getRoles().size());
        return UserDetailsImpl.build(user); // Ensure UserDetailsImpl exists and is correct
    }
}

